#include <stdio.h>
#include <stdlib.h>
#include <ascauth.h>

#define MAX_CONTEXT 512

int main(void)
{
    ASCENV *asce;
    char *context;
    int rc;
    const char *user = "jdoe";

    /* allocate buffer */
    context = (char *)malloc(MAX_CONTEXT);
    if (context == NULL) {
        fprintf(stderr, "Failed to allocate buffer\n");
        return EXIT_FAILURE;
    }

    /* initialize authentication environment */
    asce = ASC_INIT(NULL);
    if (asce == NULL) {
        fprintf(stderr, "Error: cannot initialize authentication environment\n");
        free(context);
        return EXIT_FAILURE;
    }

    /* get the user's context */
    rc = ASC_GETCONTEXT(asce, (char *)user, context, MAX_CONTEXT);
    if (rc == AS_OK) {
        printf("Context for %s: %s\n", user, context);
    } else {
        printf("ASC_GETCONTEXT failed: RC=%d, %s\n", rc, ASC_STRERROR(rc));
    }

    /* clean up */
    free(context);
    ASC_TERM(asce);
    return EXIT_SUCCESS;
}
